//! Cross-checks `BSpline2D::eval`/`derivative_x`/`derivative_y` against
//! `scipy.interpolate.RectBivariateSpline` ground truth.
//!
//! `tests/fixtures/spline_psf_small.txt` was generated by
//! `gen_spline_fixture.py` (a one-off script, not part of the repo) fitting
//! a synthetic bicubic `RectBivariateSpline` and evaluating it (and its
//! `dx=1`/`dy=1` partial derivatives) at interior, near-edge, on-knot, and
//! out-of-domain query points.

use std::fs;
use std::path::Path;

use psf::bspline::BSpline2D;

fn fixture_path() -> std::path::PathBuf {
    Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures")).join("spline_psf_small.txt")
}

fn parse_floats(line: &str) -> Vec<f64> {
    line.split_whitespace()
        .map(|s| s.parse::<f64>().expect("fixture value must parse as f64"))
        .collect()
}

#[test]
fn eval_and_derivatives_match_scipy() {
    let text = fs::read_to_string(fixture_path()).expect("failed to read fixture");
    let mut lines = text.lines();

    let header = lines.next().unwrap();
    let mut parts = header.split_whitespace();
    let n_tx: usize = parts.next().unwrap().parse().unwrap();
    let n_ty: usize = parts.next().unwrap().parse().unwrap();
    let n_c: usize = parts.next().unwrap().parse().unwrap();
    let kx: usize = parts.next().unwrap().parse().unwrap();
    let ky: usize = parts.next().unwrap().parse().unwrap();

    let tx = parse_floats(lines.next().unwrap());
    let ty = parse_floats(lines.next().unwrap());
    let c = parse_floats(lines.next().unwrap());
    assert_eq!(tx.len(), n_tx);
    assert_eq!(ty.len(), n_ty);
    assert_eq!(c.len(), n_c);

    let n_q: usize = lines.next().unwrap().trim().parse().unwrap();
    let qx = parse_floats(lines.next().unwrap());
    let qy = parse_floats(lines.next().unwrap());
    let expected_vals = parse_floats(lines.next().unwrap());
    let expected_dvals_dx = parse_floats(lines.next().unwrap());
    let expected_dvals_dy = parse_floats(lines.next().unwrap());
    assert_eq!(qx.len(), n_q);

    let spline = BSpline2D::new(tx, ty, c, kx, ky).expect("valid spline");
    let dspline_da = spline.derivative_x();
    let dspline_db = spline.derivative_y();

    for i in 0..n_q {
        let got = spline.eval(qx[i], qy[i]);
        assert!(
            (got - expected_vals[i]).abs() < 1e-10,
            "eval mismatch at ({}, {}): got {got}, expected {}",
            qx[i],
            qy[i],
            expected_vals[i]
        );

        let got_dx = dspline_da.eval(qx[i], qy[i]);
        assert!(
            (got_dx - expected_dvals_dx[i]).abs() < 1e-8,
            "d/dx mismatch at ({}, {}): got {got_dx}, expected {}",
            qx[i],
            qy[i],
            expected_dvals_dx[i]
        );

        let got_dy = dspline_db.eval(qx[i], qy[i]);
        assert!(
            (got_dy - expected_dvals_dy[i]).abs() < 1e-8,
            "d/dy mismatch at ({}, {}): got {got_dy}, expected {}",
            qx[i],
            qy[i],
            expected_dvals_dy[i]
        );
    }
}
